const orders = $input.all();
const today = new Date();

return orders.map(item => {
  const order = item.json;
  const deliveryDate = new Date(order.delivery_date);
  const daysUntil = Math.ceil((deliveryDate - today) / (1000 * 60 * 60 * 24));
  return { json: { ...order, daysUntilDelivery: daysUntil } };
});

const order = $input.first().json;
const html = '<html><body style="font-family:Arial,sans-serif;padding:20px;"><h2 style="color:#059669;">Sales Order Update</h2><p>Dear ' + (order.customer_name || 'Customer') + ',</p><p>Your order <strong>#' + order.so_number + '</strong> is scheduled for delivery in <strong>' + order.daysUntilDelivery + ' days</strong>.</p><table style="border-collapse:collapse;margin:20px 0;"><tr><td style="padding:8px;border:1px solid #ddd;">Product:</td><td style="padding:8px;border:1px solid #ddd;">' + order.product_name + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Quantity:</td><td style="padding:8px;border:1px solid #ddd;">' + order.quantity + '</td></tr><tr><td style="padding:8px;border:1px solid #ddd;">Status:</td><td style="padding:8px;border:1px solid #ddd;">' + order.status + '</td></tr></table><p>Thank you for your business!</p></body></html>';

return [{ json: { to: order.customer_email, subject: 'Order Update - #' + order.so_number, html: html, order: order } }];
